DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.save_meet_seeding(uuid,integer,integer,integer,text,boolean,numeric,jsonb,boolean)'::regprocedure) INTO d;d:=replace(d,'IF p_close AND EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows) x WHERE x->>''status''<>''SCR'' GROUP BY x->>''eventId'',x->>''heat'' HAVING count(*)<3 AND (SELECT count(*) FROM jsonb_array_elements(p_rows) y WHERE y->>''eventId''=x->>''eventId'' AND y->>''status''<>''SCR'')>=3)','IF p_close AND EXISTS(SELECT 1 FROM (SELECT x->>''eventId'' event_key,x->>''heat'' heat_key,count(*) n FROM jsonb_array_elements(p_rows) x WHERE x->>''status''<>''SCR'' GROUP BY x->>''eventId'',x->>''heat'') h JOIN (SELECT y->>''eventId'' event_key,count(*) n FROM jsonb_array_elements(p_rows) y WHERE y->>''status''<>''SCR'' GROUP BY y->>''eventId'') totals ON totals.event_key=h.event_key WHERE h.n<3 AND totals.n>=3)');EXECUTE d;END $$;